begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_table('public','fms_stage_assignment_decisions','ownership decisions belong to durable visits');
select has_table('public','fms_stage_assignment_intents','deferred handoffs are durable');
select has_function('public','resolve_fms_visit_assignment',array['uuid','uuid','uuid','uuid'],'causal visit assignment is centralized');
\ir helpers/fms_visit_assignment_fixture.psql
select is((select assigned_to from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='call')),array[(select id from visit_assignment_fixture where name='b')],'initial form assigns B rather than configured default A');
select ok(not (select context ? '_fms_assignment_user_id' from fms_instances where id=(select id from visit_assignment_fixture where name='instance')),'version two has no global future owner');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='b_auth'),true);
select lives_ok($$select submit_fms_form_and_progress_with_audit((select id from visit_assignment_fixture where name='form'),jsonb_build_object('next_employee',(select id from visit_assignment_fixture where name='c')),'fms_stage',(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='call')),gen_random_uuid())$$,'B completes and chooses C atomically');
select is((select assigned_to from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='demo')),array[(select id from visit_assignment_fixture where name='c')],'demo belongs to C, not B or default A');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='c_auth'),true);
select lives_ok($$select submit_fms_form_and_progress_with_audit((select id from visit_assignment_fixture where name='form'),jsonb_build_object('next_employee',(select id from visit_assignment_fixture where name='d')),'fms_stage',(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='demo')),gen_random_uuid())$$,'C chooses D');
select is((select assigned_to from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='negotiation')),array[(select id from visit_assignment_fixture where name='d')],'negotiation belongs to D');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='d_auth'),true);
select lives_ok($$select submit_fms_form_and_progress_with_audit((select id from visit_assignment_fixture where name='form'),jsonb_build_object('next_employee',(select id from visit_assignment_fixture where name='e')),'fms_stage',(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='negotiation')),gen_random_uuid())$$,'D chooses E');
select is((select assigned_to from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='finish')),array[(select id from visit_assignment_fixture where name='e')],'final work belongs to E');
reset role;
select throws_ok($$select resolve_fms_visit_assignment((select id from visit_assignment_fixture where name='instance'),(select id from visit_assignment_fixture where name='finish'),(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='negotiation')),(select id from visit_assignment_fixture where name='a'))$$,'42501','Employee is outside your permitted FMS handoff scope','staff cannot hand off to protected management by forged ID');
select throws_ok($$select resolve_fms_visit_assignment((select id from visit_assignment_fixture where name='instance'),(select id from visit_assignment_fixture where name='locked'),(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='negotiation')),(select id from visit_assignment_fixture where name='e'))$$,'23514','Step Locked is locked to its published fixed employee','a fixed employee rejects rather than silently ignoring an override');
select is((resolve_fms_visit_assignment((select id from visit_assignment_fixture where name='instance'),(select id from visit_assignment_fixture where name='locked'),(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='negotiation')),null)->'effectiveUserIds'),jsonb_build_array((select id from visit_assignment_fixture where name='a')),'an explicitly locked published owner remains authoritative');
select is((select count(*)::integer from fms_stage_assignment_decisions where fms_instance_id=(select id from visit_assignment_fixture where name='instance')),4,'every actionable activation has its own durable ownership decision');
select is((select count(*)::integer from fms_stage_assignment_decisions where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and source_submission_id is not null),4,'all decisions retain their exact source submissions');
select ok(not has_table_privilege('authenticated','fms_stage_assignment_decisions','INSERT'),'browser cannot forge assignment history');
select ok(not has_function_privilege('authenticated','resolve_fms_visit_assignment(uuid,uuid,uuid,uuid)','EXECUTE'),'browser cannot bypass the protected transition boundary');
select * from finish();
rollback;
